<?php require_once 'config/functions.php';require_login();$uid=user_id();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$pdo->prepare('INSERT INTO moods(user_id,mood_date,mood,note) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE mood=VALUES(mood),note=VALUES(note)')->execute([$uid,$_POST['mood_date'],$_POST['mood'],trim($_POST['note']??'')]);flash('Mood recorded. Thank you for checking in with yourself.');redirect('mood.php');}$q=$pdo->prepare('SELECT * FROM moods WHERE user_id=? ORDER BY mood_date DESC LIMIT 20');$q->execute([$uid]);$records=$q->fetchAll();page_header('Mood Tracker');?><div class="grid grid-2"><div class="card"><h3>How are you feeling today?</h3><form class="form" method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><div class="field"><label>Date</label><input type="date" name="mood_date" value="<?=date('Y-m-d')?>" required></div><div class="moods"><?php foreach(['Happy'=>'😊','Calm'=>'😌','Loved'=>'🥰','Excited'=>'🤩','Okay'=>'🙂','Sad'=>'😢','Anxious'=>'😰','Angry'=>'😠','Tired'=>'😴'] as $name=>$emoji):?><label class="mood-option"><input type="radio" name="mood" value="<?=$name?>" required><span><?=$emoji?> <?=$name?></span></label><?php endforeach;?></div><div class="field"><label>Note (optional)</label><textarea name="note" placeholder="What is affecting your mood?" style="min-height:90px"></textarea></div><button>Save Mood</button></form></div><div class="card"><h3>Your mood history</h3><?php if(!$records):?><div class="empty">Your mood history will appear here.</div><?php else:foreach($records as $r):?><div class="entry"><strong><?=h($r['mood'])?></strong><span class="small"> · <?=h($r['mood_date'])?></span><p><?=h($r['note'])?></p></div><?php endforeach;endif;?></div></div><?php page_footer();
